data.methods:
/**
 * Custom method for custom view in MapX
 * Parameters for onInit and onClose function ;
 * @param {Object} o Options
 * @param {Object} o.view Map-x view object
 * @param {Object} o.map mapbox-gl map object
 * @param {String} o.idView If of the view
 * @param {String} o.idSource Id of the source
 * @param {Element} o.elLegend Element containing the legend
 *
 */
return {
    onClose: function(o) {
        console.log("Custom view closed");
        /**
         * Remove source
         */
        o.onRemove();

    },
    onInit: function(o) {
        console.log("Custom view added");

        var h = mx.helpers,
            s = mx.settings,
            el = h.el;
        map = o.map;

        var url = "https://storage.googleapis.com/global-surface-water/maptiles/wetlands/{z}/{x}/{y}.png",
            legendTitle = "Wetlands",
            legendEls = [{
                    label: "Wetlands",
                    color: "#7cafa7"
                }
            ];

        /**
         * Set custom source
         */
        o.source = {
            "type": "raster",
            "tiles": [url],
        };

        /**
         * Set custom layer
         */
        o.layer = {
            "id": o.idView,
            "type": "raster",
            "source": o.idSource
        };

        /**
         * Set custom legend
         */
        createLegend();

        /**
         * Set layer and source
         */
        o.map.addSource(o.idSource, o.source);
        o.map.addLayer(o.layer, mx.settings.layerBefore);

        /**
         * Helpers
         */
        function createLegend() {
            var legend;

            var legendCont = el("div", {
                    class: ['mx-legend-box'],
                    style: {
                        display: "flex",
                        flexDirection: "column"
                    }
                },
                legend = el("div", legendTitle, {
                    style: {
                        display: "flex",
                        alignItems: "flex-start",
                        justifyContent: "flex-start",
                        fontSize: "0.9em",
                        color: "#777",
                        marginBottom: "10px"
                    }
                }));

            legendEls.forEach(e => createLegendEl(e, legendCont));

            o.elLegend.appendChild(legendCont);
        }

        function createLegendEl(e, parent) {
            var elRow = el("div", {
                    style: {
                        display: "flex",
                        flexDirection: "row",
                        alignItems: "center",
                        justifyContent: "flex-start",
                        paddingBottom: "5px"
                    }
                },
                el("span", {
                    style: {
                        height: "7px",
                        width: "7px",
                        backgroundColor: e.color,
                        borderRadius: "50%"
                    },
                }),
                el("span", e.label, {
                    style: {
                        height: "100%",
                        fontSize: "0.9em",
                        paddingLeft: "8px"
                    }
                }));

            parent.appendChild(elRow);
        }

        /**
         * Remove added layers
         */
        o.onRemove = function() {
            var layer = o.map.getLayer(o.idView);
            var source = o.map.getSource(o.idSource);
            if (layer) {
                o.map.removeLayer(o.idView);
            }
            if (source) {
                o.map.removeSource(o.idSource);
            }
        };

    }
};

widgets.script:
/** 
 * Add functions to handle dashboard events
 * onAdd = Action to exectute when the widget is added to the DOM
 * onRemove = Action to execute when the widget is removed
 * onData = Action to execute when data is updated. Data is available with this.data 
 */
return {
  onAdd: function (widget) {
    /**
     * shortcuts
     */
    const w = widget;
    const h = mx.helpers;
    const s = mx.settings;
    const d = w.config.dashboard;
    const el = h.el;
    const elContent = w.elContent;

    /**
     * variables dictionary
     */
    d.dico = [{
      indicator: "chl",
      unit: "mg m-3",
      unit_html: "mg/m<SUP>3</SUP>",
      label_short: "Total Chlorophyll",
      label: "Mass Concentration of Chlorophyll In Sea Water"
    },
    {
      indicator: "fe",
      unit: "mmol m-3",
      unit_html: "mmol/m<SUP>3</SUP>",
      label_short: "Dissolved Iron",
      label: "Mole Concentration of Dissolved Iron In Sea Water"
    },
    {
      indicator: "no3",
      unit: "mmol m-3",
      unit_html: "mmol/m<SUP>3</SUP>",
      label_short: "Nitrate",
      label: "Mole Concentration of Nitrate In Sea Water"
    },
    {
      indicator: "nppv",
      unit: "mg m-3 day-1",
      unit_html: "mg/m<SUP>3</SUP>/day",
      label_short: "Total Primary Production of Phyto",
      label: "Net Primary Production of Biomass Expressed As Carbon Per Unit Volume In Sea Water"
    },
    {
      indicator: "o2",
      unit: "mmol m-3",
      unit_html: "mmol/m<SUP>3</SUP>",
      label_short: "Dissolved Oxygen",
      label: "Mole Concentration of Dissolved Molecular Oxygen In Sea Water"
    },
    {
      indicator: "ph",
      unit: "",
      unit_html: "",
      label_short: "pH",
      label: "Sea Water pH Reported On Total Scale"
    },
    {
      indicator: "phyc",
      unit: "mmol m-3",
      unit_html: "mmol/m<SUP>3</SUP>",
      label_short: "Total Phytoplankton",
      label: "Mole Concentration of Phytoplankton Expressed As Carbon In Sea Water"
    },
    {
      indicator: "po4",
      unit: "mmol m-3",
      unit_html: "mmol/m<SUP>3</SUP>",
      label_short: "Phosphate",
      label: "Mole Concentration of Phosphate In Sea Water"
    },
    {
      indicator: "si",
      unit: "mmol m-3",
      unit_html: "mmol/m<SUP>3</SUP>",
      label_short: "Dissolved Silicate",
      label: "Mole Concentration of Silicate In Sea Water"
    },
    {
      indicator: "spco2",
      unit: "Pa",
      unit_html: "Pa",
      label_short: "Surface CO2",
      label: "Surface Partial Pressure of Carbon Dioxide In Sea Water"
    }
    ];

    /**
     * years
     */
    const currentTime = new Date();
    const year = currentTime.getFullYear();
    const month = currentTime.getMonth() + 1;
    const yearMin = 2020;
    const yearMax = month == 1 ? year - 1 : year;

    /**
     * UI
     */
    let elSelect,
      elInput,
      elLabel;

    const elDrop =
      el("div", {
        style: {
          display: "flex",
          flexDirection: "row",
          height: "100%",
          width: "100%",
          padding: "10px"
        }
      },
        el("div", {
          style: {
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            height: "100%",
            width: "55%"
          }
        },
          el("span", "Parameter:", {
            style: {
              fontWeight: "bold",
              paddingRight: "10px"
            },
          }),
          elSelect = el("select", {
            class: ["form-control"],
            style: {
              //height: "90%",
              width: "70%",
              fontSize: "0.95em",
              zIndex: 100
            },
            on: {
              "change": updateDashboard
            }
          })),
        el("div", {
          style: {
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            height: "100%",
            width: "45%"
          }
        },
          el("span", "Year:", {
            style: {
              fontWeight: "bold",
              paddingRight: "10px"
            },
          }),
          el("div", {
            style: {
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              height: "60%",
              width: "100%"
            }
          },
            elInput = el("INPUT", {
              type: "range",
              min: yearMin,
              max: yearMax,
              step: "1",
              value: yearMax,
              style: {
                order: "1",
                width: "140px",
                zIndex: "2"
              },
              on: {
                'input': updateDashboard
              }
            }),
            elLabel = el("span", {
              style: {
                order: "2",
                fontStyle: "italic",
                marginLeft: "15px"
              }
            }))));
    elContent.appendChild(elDrop);
    d.dico.forEach(d => addOptions(elSelect, d.indicator, d.label_short));


    /**
     * init inputs and chart(s)
     */
    updateDashboard();

    /**
     * update charts based on select input
     */
    function updateDashboard() {
      w.indicator = elSelect.value;
      w.year = elInput.value;
      elLabel.innerText = elInput.value;
      if (w.data) {
        data = w.data[0];
        d.updateChart(data.geoname, data.mrgid, w.indicator, w.year);
      }
    }

    /**
     * add options to dropdown list
     */
    function addOptions(select, value, label) {
      const option = document.createElement("option");
      option.value = value;
      option.innerText = label;
      select.appendChild(option);
    }

    /**
     * clean widget on remove
     */
    w.clean = function () {
      elSelect.removeEventListener("change", updateDashboard);
    };

  },
  onRemove: function (widget) {
    /**
     * shortcuts
     */
    const w = widget;

    /**
     * clean widget on remove
     */
    w.clean();
  },
  onData: function (widget, data) {
    /**
     * shortcuts
     */
    const w = widget;
    const h = mx.helpers;
    const d = w.config.dashboard;
    data = data[0];

    /**
    * setup map highlight
    */
    mx.highlighter.set({
      filters: [{
        id: "MX-VKW3P-AE6B0-0JY3H",
        filter: [
          "==",
          ["get", "mrgid"],
          data.mrgid
        ],
      }]
    });

    /**
     * update chart
     */
    d.updateChart(data.geoname, data.mrgid, w.indicator, w.year);
  }
};

/** 
 * Add functions to handle dashboard events
 * onAdd = Action to exectute when the widget is added to the DOM
 * onRemove = Action to execute when the widget is removed
 * onData = Action to execute when data is updated. Data is available with this.data 
 */
return {
  onAdd: function (widget) {
    /**
     * shortcuts
     */
    const w = widget;
    const h = mx.helpers;
    const s = mx.settings;
    const d = w.config.dashboard;
    const el = h.el;
    const elContent = w.elContent;
    const hc = w.modules.highcharts;

    /**
     * variable
     */
    const tableMapX = "mx_vector_ukhyo_qzoqn_htsba_orxgy";

    /**
     * UI
     */
    let elChart,
      elMeta;

    const elCont = el("div", {
      style: {
        height: "375px",
      }
    },
      elChart = el("div", {
        style: {
          height: "100%",
        }
      }),
      elMeta = el("span", {
        class: "fa fa-info-circle",
        style: {
          position: "absolute",
          top: "10px",
          left: "10px",
          color: "royalblue",
          cursor: "pointer",
          zindex: 100
        }
      }));
    elContent.appendChild(elCont);
    elMeta.addEventListener('click', getMetaInPanel);


    /**
     * chart design
     */
    const chart = hc.chart(elChart, {
      chart: {
        zoomType: "xy",
        inverted: false
      },

      title: {
        text: "Click on an EEZ to visualize monthly mean data!",
        style: {
          fontWeight: "bold",
          fontSize: "1.2em",
          color: "#000000"
        },
        margin: 30
      },

      subtitle: {
        text: ""
      },

      xAxis: {
        categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
        labels: {
          style: {
            fontSize: "10px",
            color: "#808080"
          }
        },
        min: 0,
        max: 11
      },

      yAxis: {
        title: {
          text: "",
          align: "high",
          offset: 0,
          useHTML: true,
          rotation: 0,
          y: -15
        },
        labels: {
          format: "{value}",
          style: {
            fontSize: "10px",
            color: "#808080"
          },
        }
      },

      tooltip: {
        crosshairs: true,
        shared: true,
        useHTML: true,
        valueDecimals: 3
      },

      exporting: {
        buttons: {
          contextButton: {
            menuItems: [
              'downloadPNG',
              'downloadJPEG',
              'downloadSVG',
              'separator',
              'downloadCSV',
              'downloadXLS'
            ]
          }
        }
      },

      navigation: {
        buttonOptions: {
          align: 'right'
        }
      },

      credits: {
        enabled: false
      },

      series: [{
        name: 'Mean',
        data: [undefined],
        zIndex: 1,
        color: '#4CA6FF',
        marker: {
          fillColor: 'white',
          lineWidth: 2,
          lineColor: '#4CA6FF'
        }
      }, {
        name: 'Min - Max',
        data: [
          [undefined, undefined]
        ],
        type: 'arearange',
        lineWidth: 0,
        linkedTo: ':previous',
        color: '#4CA6FF',
        fillOpacity: 0.1,
        zIndex: 0,
        marker: {
          enabled: false
        }
      }]
    });

    /**
     * update chart based on inputs
     */
    async function updateChart(geoname, mrgid, indicator, year) {
      const title = d.dico.find(d => d.indicator == indicator).label;
      const unit = d.dico.find(d => d.indicator == indicator).unit_html;

      const data = await fetchData(tableMapX, mrgid, indicator, year);
      const meanArr = data.map(d => d.mean);
      const minMaxArr = data.map(d => [d.min, d.max]);

      chart.update({
        title: {
          text: `${title} (${year})`,
        },

        subtitle: {
          text: geoname
        },

        yAxis: {
          title: {
            text: unit
          }
        },

        tooltip: {
          valueSuffix: ` ${unit}`
        },

        series: [{
          data: meanArr,
        }, {
          data: minMaxArr,
        }]
      });

    }
    d.updateChart = updateChart;

    /**
     * fetch data
     */
    async function fetchData(table, mrgid, indicator, year) {
      const query = `SELECT month, min, max, mean FROM ${table} WHERE mrgid = ${mrgid} AND indicator = '${indicator}' AND year = ${year} ORDER BY month ASC`;
      const url = new URL(h.getApiUrl("getApiSql"));
      url.searchParams.set("sql", query);
      const response = await fetch(url);
      const data = await response.json();
      return data;
    }

    /**
     * Display the metadata in a panel
     */
    async function getMetaInPanel() {
      h.sourceToMetaModal(tableMapX);
    }
  },
  onRemove: function (widget) { },
  onData: function (widget, data) { }
};

data.methods:
/**
 * Custom method for custom view in MapX
 * Parameters for onInit and onClose function ;
 * @param {Object} o Options
 * @param {Object} o.view Map-x view object
 * @param {Object} o.map mapbox-gl map object
 * @param {String} o.idView If of the view
 * @param {String} o.idSource Id of the source
 * @param {Element} o.elLegend Element containing the legend
 *
 */
return {
    onClose: function(o) {
        /**
         * Remove source
         */
        o.onRemove();

    },
    onInit: function(o) {
        const h = mx.helpers;
        const el = h.el;

        var categories = [{
                label: "Tree cover",
                color: "rgb(0,100,0)"
            },
            {
                label: "Shrubland",
                color: "rgb(255, 187, 34)"
            },
            {
                label: "Grassland",
                color: "rgb(255, 255, 76)"
            },
            {
                label: "Cropland",
                color: "rgb(240, 150, 255)"
            },
            {
                label: "Built-up",
                color: "rgb(250, 0, 0)"
            },
            {
                label: "Bare/sparse vegetation",
                color: "rgb(180, 180, 180)"
            },
            {
                label: "Snow and Ice",
                color: "rgb(240, 240, 240)"
            },
            {
                label: "Permanent water bodies",
                color: "rgb(0, 100, 200)"
            },
            {
                label: "Herbaceous wetland",
                color: "rgb(0, 150, 160)"
            },
            {
                label: "Mangroves",
                color: "rgb(0, 207, 117)"
            },
            {
                label: "Moss and lichen",
                color: "rgb(250, 230, 160)"
            }
        ];

        setLegend(categories);

        let url = getUrl('WORLDCOVER_2021_MAP');

        /**
         * Set custom source
         */
        o.source = {
            type: 'raster',
            tiles: [url],
            tileSize: 512
        };

        /**
         * Set custom layer
         */
        o.layer = {
            id: o.idView,
            type: "raster",
            source: o.idSource,
            paint: {}
        };

        /**
         * Set layer and source
         */
        o.map.addSource(o.idSource, o.source);
        o.map.addLayer(o.layer, mx.settings.layerBefore);


        /**
         * Helpers
         */
        function getUrl(layer) {
            var url = 'https://services.terrascope.be/wms/v2?';
            out = mx.helpers.objToParams({
                bbox: 'bboxcode',
                service: 'WMS',
                version: '1.1.1',
                styles: '',
                request: 'getMap',
                zindex: '10',
                srs: 'EPSG:3857',
                layers: layer,
                format: 'image/png',
                transparent: 'true',
                height: '512',
                width: '512',
                exceptions: 'application:Fvnd.ogc.se_blank'
            });
            out = out.replace('bboxcode', '{bbox-epsg-3857}');
            out = url + out;
            return out;
        }

        function setLegend(categories) {
            if (h.isElement(o.elLegend)) {

                var elLegendContent = el("div", {
                        class: ['mx-legend-box'],
                        style: {
                            display: "flex",
                            flexDirection: "column"
                        }
                    },
                    el('div', 'Land Cover Class', {
                        style: {
                            paddingLeft: '10px',
                            marginBottom: '10px'
                        }
                    }),
                    categories.map(e => {
                        return el('div', {
                                style: {
                                    display: 'flex',
                                    flexDirection: 'row',
                                    justifyContent: 'flex-start',
                                    alignItems: 'center'
                                }
                            },
                            el('span', {
                                style: {
                                    width: '20px',
                                    height: '20px',
                                    marginRight: '5px',
                                    background: e.color
                                }
                            }),
                            el('span', e.label));
                    }));
                o.elLegend.appendChild(elLegendContent);
            }
        }

        /**
         * Remove added layers
         */
        o.onRemove = function() {
            var layer = o.map.getLayer(o.idView);
            var source = o.map.getSource(o.idSource);
            if (layer) {
                o.map.removeLayer(o.idView);
            }
            if (source) {
                o.map.removeSource(o.idSource);
            }
        };

    }
};

/**
 * Custom method for custom view in MapX
 * Parameters for onInit and onClose function ;
 * @param {Object} o Options
 * @param {Object} o.view Map-x view object
 * @param {Object} o.map mapbox-gl map object
 * @param {String} o.idView If of the view
 * @param {String} o.idSource Id of the source
 * @param {Element} o.elLegend Element containing the legend
 *
 */
return {
  onClose: function (o) {
    return;
    console.log("Custom view closed");
    if (o._clean) o._clean();
  },
  onInit: function (o) {
    return;
    console.log("Custom view added");
    const map = o.map;
    const el = mx.helpers.el;
    let idTimeout;

    const now = formatDate(new Date());
    const initLabel = `From: ${now} <br>To: ${now}`;
    const defaultSensor = "fires_modis";
    const options = [{
      value: "fires_modis",
      en: "MODIS"
    },
    {
      value: "fires_aqua",
      en: "MODIS-Aqua"
    },
    {
      value: "fires_terra",
      en: "MODIS-Terra"
    },
    {
      value: "fires_viirs",
      en: "VIIRS"
    }
    ];

    /**
     * sensor options
     */
    let elSelectSensor,
      elInput,
      elDay;

    const elOptions = el("div", {
      class: ["mx-legend-box"],
      style: {
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        justifyContent: "flex-start"
      }
    },
      el("label", "FIRMS layer"),
      elSelectSensor = el("select", {
        class: ["form-control"],
        style: {
          width: "70%",
          height: "70%",
          fontSize: "0.9em",
        },
        on: {
          "change": updateWMS
        }
      }),
      el("label", "Time period (in days)", {
        style: {
          paddingTop: "15px"
        },
      }),
      el("div", {
        style: {
          display: "flex",
          flexDirection: "row",
          alignItems: "center"
        }
      },
        elInput = el("INPUT", {
          type: "range",
          min: "-30",
          max: "0",
          step: "1",
          value: "0",
          style: {
            width: "150px",
            zIndex: "2"
          },
          on: {
            "input": updateWMS
          }
        }),
        elDay = el("span", initLabel, {
          style: {
            fontSize: "0.9em",
            fontStyle: "italic",
            marginLeft: "15px"
          },
        })));
    options.forEach(cOption);
    o.elLegend.appendChild(elOptions);

    /**
     * Set custom source
     */
    updateMap(defaultSensor, makeTime(0));

    /**
     * HELPERS
     */

    // update WMS query
    function updateWMS() {
      clearTimeout(idTimeout);
      idTimeout = setTimeout(() => {
        const days = elInput.value;
        const layer = elSelectSensor.value;
        const time = makeTime(days);
        const dates = time.split("/");
        const date_start = dates[0];
        const date_end = dates[1];
        elDay.innerHTML = `From: ${date_start}<br>To: ${date_end}`;
        updateMap(layer, time);
      }, 10);
    }

    //Update map
    function updateMap(layer, time) {
      if (map.getLayer(o.idView)) {
        map.removeLayer(o.idView);
      }
      if (map.getSource(o.idSource)) {
        map.removeSource(o.idSource);
      }

      const url = mx.helpers.mirrorUrlCreate(getUrl(layer, time));


      map.addSource(o.idSource, {
        type: "raster",
        tiles: [url],
        tileSize: 512
      });

      map.addLayer({
        id: o.idView,
        type: "raster",
        source: o.idSource,
        paint: {}
      });
    }

    //Configure URL from an WMS source
    function getUrl(layer, time) {
      const key = "3a73d000a14ad224866835a1f6cae4ff"
      const url = `https://firms2.modaps.eosdis.nasa.gov/mapserver/wms/fires/${key}/?`;
      let out = mx.helpers.objToParams({
        bbox: "bboxcode",
        service: "WMS",
        version: "1.1.1",
        styles: "",
        request: "getMap",
        zindex: "10",
        srs: "EPSG:3857",
        layers: layer,
        time: time,
        format: "image/png",
        transparent: "true",
        height: "512",
        width: "512",
        symbols: "circle",
        size: "5",
        colors: "250+40+40"
      });
      out = out.replace("bboxcode", "{bbox-epsg-3857}");
      out = url + out;
      return out;
    }

    // format time argument for the WMS query
    function makeTime(days) {
      const dateOffset = (24 * 60 * 60 * 1000) * days;
      const time_end = new Date().getTime();
      const time_start = time_end + dateOffset;
      let date_end = new Date(time_end);
      let date_start = new Date(time_start);
      date_end = formatDate(date_end);
      date_start = formatDate(date_start);
      return date_start + "/" + date_end;
    }

    // format date as YYYY-MM-DD
    function formatDate(date) {
      const day = ("0" + date.getDate()).slice(-2);
      const month = ("0" + (date.getMonth() + 1)).slice(-2);
      const year = date.getFullYear();
      return year + "-" + month + "-" + day;
    }

    // add options to elSelectSensor
    function cOption(item) {
      const option = document.createElement("option");
      option.value = item.value;
      option.innerText = item.en;
      elSelectSensor.appendChild(option);
    }

    // remove Mapbox source and layer & eventListener
    o._clean = function () {
      if (map.getLayer(o.idView)) {
        map.removeLayer(o.idView);
      }
      if (map.getSource(o.idSource)) {
        map.removeSource(o.idSource);
      }
      elSelectSensor.removeEventListener("change", updateWMS);
      elInput.removeEventListener("input", updateWMS);
    };
  }
};

widgets.script:
function handler() {
  /**
   * Configuration
   */
  const config = {
    wmsEndpoint: "https://firms2.modaps.eosdis.nasa.gov/mapserver/wms/fires",
    apiKey: "3a73d000a14ad224866835a1f6cae4ff",
    sensors: [{
      value: "fires_modis",
      en: "MODIS"
    }, {
      value: "fires_aqua",
      en: "MODIS-Aqua"
    }, {
      value: "fires_terra",
      en: "MODIS-Terra"
    }, {
      value: "fires_viirs",
      en: "VIIRS"
    }],
    timeRange: {
      min: -30,
      max: 0,
      default: 0
    },
    updateDelay: 10, // ms
    wmsStyle: {
      symbols: "circle",
      size: "5",
      colors: "250+40+40"
    }
  };

  /**
   * Local state
   */
  const local = {
    elements: {},
    isUpdating: false,
    updateTimer: null,
    currentSensor: config.sensors[0].value,
    currentDays: config.timeRange.default
  };

  const { mx } = window;
  const { helpers } = mx;
  const { el } = helpers;

  return {
    /**
     * Widget initialization and UI setup
     */
    async onAdd(widget) {
      try {
        // Create control elements
        const controls = createControls(widget);

        // Set initial widget content
        widget.setContent(controls);

        // Initialize map
        await updateAll(widget);
      } catch (e) {
        console.error("Failed to initialize FIRMS widget:", e);
      }
    },

    /**
     * Cleanup when widget is removed
     */
    async onRemove(widget) {
      try {
        if (widget.map.getLayer(widget.view.id)) {
          widget.map.removeLayer(widget.view.id);
        }
        if (widget.map.getSource(widget.view.id)) {
          widget.map.removeSource(widget.view.id);
        }
        if (local.updateTimer) {
          clearTimeout(local.updateTimer);
        }
        local.elements = {};
      } catch (e) {
        console.error("Failed to clean up FIRMS widget:", e);
      }
    }
  };

  /**
   * Create control elements
   */
  function createControls(widget) {
    return el("div", {
      class: ["mx-widget-controls"],
      style: {
        display: "flex",
        flexDirection: "column",
        padding: "10px"
      }
    }, [
      // Sensor selector
      el("div", {
        style: {
          marginBottom: "15px"
        }
      }, [
        el("label", "FIRMS layer"),
        local.elements.sensorSelect = el("select", {
          class: ["form-control"],
          style: {
            width: "100%",
            marginTop: "5px"
          },
          on: {
            change: () => scheduleUpdate(widget)
          }
        }, config.sensors.map(s =>
          el("option", { value: s.value }, s.en)
        ))
      ]),

      // Time range selector
      el("div", [
        el("label", "Time period (in days)"),
        el("div", {
          style: {
            display: "flex",
            alignItems: "center",
            marginTop: "5px"
          }
        }, [
          local.elements.daysSlider = el("input", {
            type: "range",
            min: String(config.timeRange.min),
            max: String(config.timeRange.max),
            value: String(local.currentDays),
            style: {
              width: "150px"
            },
            on: {
              input: () => scheduleUpdate(widget)
            }
          }),
          local.elements.dateLabel = el("span", {
            style: {
              marginLeft: "15px",
              fontSize: "0.9em",
              fontStyle: "italic"
            }
          }, getDateRangeLabel(config.timeRange.default))
        ])
      ])
    ]);
  }

  /**
   * Schedule an update with debouncing
   */
  function scheduleUpdate(widget) {
    if (local.updateTimer) {
      clearTimeout(local.updateTimer);
    }

    local.currentSensor = local.elements.sensorSelect.value;
    local.currentDays = Number(local.elements.daysSlider.value);

    // Update date range label immediately
    local.elements.dateLabel.innerHTML = getDateRangeLabel(local.currentDays);

    // Schedule map update
    local.updateTimer = setTimeout(() => {
      updateAll(widget);
    }, config.updateDelay);
  }

  /**
   * Update all components
   */
  async function updateAll(widget) {
    if (local.isUpdating) return;
    local.isUpdating = true;

    try {
      await updateMap(widget);
    } catch (e) {
      console.error("Failed to update FIRMS visualization:", e);
    } finally {
      local.isUpdating = false;
    }
  }

  /**
   * Update map layer
   */
  async function updateMap(widget) {
    const map = widget.map;
    const viewId = widget.view.id;

    if (map.getLayer(viewId)) {
      map.removeLayer(viewId);
    }
    if (map.getSource(viewId)) {
      map.removeSource(viewId);
    }

    const time = calculateTimeRange(local.currentDays);
    const url = mx.helpers.mirrorUrlCreate(
      getWmsUrl(local.currentSensor, time)
    );

    map.addSource(viewId, {
      type: "raster",
      tiles: [url],
      tileSize: 512
    });

    map.addLayer({
      id: viewId,
      type: "raster",
      source: viewId,
      paint: {}
    });
  }

  /**
   * Calculate date range for given number of days
   */
  function calculateTimeRange(days) {
    const timeEnd = new Date();
    const timeStart = new Date(timeEnd);
    timeStart.setDate(timeStart.getDate() + days);
    return `${formatDate(timeStart)}/${formatDate(timeEnd)}`;
  }

  /**
   * Get formatted date range label
   */
  function getDateRangeLabel(days) {
    const timeEnd = new Date();
    const timeStart = new Date(timeEnd);
    timeStart.setDate(timeStart.getDate() + days);
    return `From: ${formatDate(timeStart)}<br>To: ${formatDate(timeEnd)}`;
  }

  /**
   * Format date as YYYY-MM-DD
   */
  function formatDate(date) {
    return date.toISOString().split('T')[0];
  }

  /**
   * Configure URL for WMS tiles
   */
  function getWmsUrl(layer, time) {
    const baseUrl = `${config.wmsEndpoint}/${config.apiKey}/?`;
    let params = mx.helpers.objToParams({
      bbox: "bboxcode",
      service: "WMS",
      version: "1.1.1",
      styles: "",
      request: "getMap",
      zindex: "10",
      srs: "EPSG:3857",
      layers: layer,
      time: time,
      format: "image/png",
      transparent: "true",
      height: "512",
      width: "512",
      ...config.wmsStyle
    });
    params = params.replace("bboxcode", "{bbox-epsg-3857}");
    return baseUrl + params;
  }
}

data.methods:
/**
 * Custom method for custom view in MapX
 * Parameters for onInit and onClose function ;
 * @param {Object} o Options
 * @param {Object} o.view Map-x view object
 * @param {Object} o.map mapbox-gl map object
 * @param {String} o.idView If of the view
 * @param {String} o.idSource Id of the source
 * @param {Element} o.elLegend Element containing the legend
 *
 */
return {
    onClose: function(cc) {
        if (cc._clear) {
            cc._clear();
        }
    },
    onInit: function(cc) {
        const h = mx.helpers;
        const s = mx.settings;
        const el = h.el;
        const sep = s.separators.sublayer;
        const idMxLayer = s.layerBefore;

        /**
         * Variables
         */
        const colorWater = "#87CEEB";
        const waterAlt = {
            "id": `${cc.idView}${sep}water_alt`,
            "type": "fill",
            "source": "mapbox_composite",
            "source-layer": "water",
            "layout": {
                "visibility": "visible"
            },
            "paint": {
                "fill-color": colorWater,
                "fill-opacity": 0.8,
                "fill-antialias": false
            }
        };

        /**
         * Label dictionary for UNMap boundaries
         */
        const dictUN = [{
            id: "boundary_un_1",
            label: "International boundary"
        }, {
            id: "boundary_un_2",
            label: "Special boundary line"
        }, {
            id: "boundary_un_3",
            label: "Armistice or international administrative line"
        }, {
            id: "boundary_un_4",
            label: "Other line of separation"
        }, {
            id: "boundary_un_8",
            label: "Autonomous region boundary"
        }, {
            id: "boundary_un_9",
            label: "Sovereign base limit"
        }, {
            id: "boundary_un_6",
            label: "Administrative boundary (level 1)"
        }];

        /**
         * Create layer store
         *          
         * Same as mapbox methods :
         * const style = o.map.getStyle();
         * const boundaries = style.layers.filter(s => /^boundary_un/.test(s.id));
         */
        const boundaries = [];
        const boundariesOrig = h.getLayerByPrefix({
            prefix: 'boundary_un'
        });
        for (const boundaryOrig of boundariesOrig) {
            const boundary = h.clone(boundaryOrig);
            boundary.id = `${cc.idView}${sep}${boundary.id}`;
            boundaries.push(boundary);
        }

        /*
         * Initial render
         */
        render();

        /**
         * Render borders from initial style, and use theme hl colors as line
         * color.
         * Water bodies are added to hide admin boundaries in disputed area.
         */
        function render() {
            //const hlColor = mx.theme.get('mx_map_feature_highlight').color;
            const hlColor = mx.theme.getColorThemeItem('mx_map_feature_highlight');


            /*
             * Clean in case of udpate
             */
            if (cc._clear) {
                cc._clear();
            }

            /*
             * Setup basic legend container with proper class
             */
            const elLegendContent = el('div', {
                class: ['mx-legend-box'],
                style: {
                    display: 'flex',
                    flexDirection: 'column',
                    fontSize: '0.9em'
                }
            });
            cc.elLegend.appendChild(elLegendContent);

            /*
             * Re-render when theme change
             */
            mx.theme.on("set_colors", render);

            /**
             * UNMap admin boundaries
             */
            let priority = 0;
            for (const boundary of boundaries) {
                /**
                 * Get UN level
                 */
                const pos = boundary.id.split(/_/)[2];

                /*
                 * Alter style depending on level
                 */
                /*
                switch (pos) {
                    case '1':
                        boundary.paint['line-width'] = 2;
                        break;
                    case '2':
                    case '3':
                        boundary.paint['line-width'] = 1;
                        break;
                    default:
                        boundary.paint['line-width'] = 0.5;
                }
                */

                switch (pos) {
                    case '6':
                        boundary.paint['line-width'] = 0.2;
                        break;
                    default:
                        boundary.paint['line-width'] = 1.2;
                }

                boundary.paint['line-color'] = hlColor;
                boundary.paint['line-opacity'] = 0.8;

                /**
                 *  Required by position resolver, e.g. user change position
                 *  in the list
                 */
                boundary.metadata = {
                    priority: priority++,
                    position: 1,
                    idView: cc.idView
                };
                cc.map.addLayer(boundary, idMxLayer);

                /**
                 * Build legend item
                 */
                const elLegendRow = buildLegendRowLine(boundary);
                elLegendContent.appendChild(elLegendRow);
            }

            /**
             * Water bodies
             */

            /**
             *  Required by position resolver, e.g. user change position
             *  in the list
             */
            waterAlt.metadata = {
                priority: priority++,
                position: 0,
                idView: cc.idView
            };
            cc.map.addLayer(waterAlt, idMxLayer);

            /**
             * Build legend item
             */
            const elLegendRow = buildLegendRowPoly(colorWater, "Water bodies");
            elLegendContent.appendChild(elLegendRow);

        }

        function buildLegendRowLine(layer) {
            const W = 25;
            const H = 15;

            const sLine = h.svg('svg', {
                    width: W,
                    height: H,
                    viewBox: `0 0  ${W} ${H}`
                },
                h.svg(
                    'line', {
                        x1: 0,
                        x2: W,
                        y1: H / 2,
                        y2: H / 2,
                        stroke: layer.paint['line-color'],
                        'stroke-width': layer.paint['line-width'],
                        'stroke-dasharray': layer.paint['line-dasharray']
                    })
            );

            const idLayer = layer.id.split(sep)[1];
            const label = dictUN.find(d => d.id == idLayer).label;

            const elRow = el('div', {
                    style: {
                        display: 'flex',
                        flexDirection: 'row',
                        justifyContent: 'flex-start',
                        alignItems: 'center'
                    }
                },
                el('span', sLine),
                el('span', label, {
                    style: {
                        height: '100%',
                        fontSize: '0.9em',
                        marginLeft: '10px'
                    }
                }));
            return elRow;
        }

        function buildLegendRowPoly(color, label) {
            const elRow = el('div', {
                    style: {
                        display: 'flex',
                        flexDirection: 'row',
                        justifyContent: 'flex-start',
                        alignItems: 'center'
                    }
                },
                el('span', {
                    style: {
                        width: '25px',
                        height: '25px',
                        background: color
                    }
                }),
                el('span', label, {
                    style: {
                        height: '100%',
                        fontSize: '0.9em',
                        marginLeft: '10px'
                    }
                }));
            return elRow;
        }

        /**
         * Remove added layers
         */
        cc._clear = function() {
            mx.theme.off("set_colors", render);

            /**
             * UNMap
             */
            for (const boundary of boundaries) {
                const layerAdm = cc.map.getLayer(boundary.id);
                if (layerAdm) {
                    cc.map.removeLayer(boundary.id);
                }
            }

            /**
             * Water bodies
             */
            const layerWater = cc.map.getLayer(waterAlt.id);
            if (layerWater) {
                cc.map.removeLayer(layerWater.id);
            }

            while (cc.elLegend.firstElementChild) {
                cc.elLegend.firstElementChild.remove();
            }
        };
    }
};

widgets.script:
/**
 * Widget handler
 */
function handler() {
  return {
    /**
     * Callback called once when the widget is added
     * @param { Widget } widget - The widget instance.
     * @property { Object } widget.opt - Widget options
     * @property { Object } widget.opt.map - The map.
     * @property { Object } widget.opt.view - The view
     * @property { Object } widget.opt.dashboard - The dashboard instance
     * @property { string } widget.id - The ID of the widget.
     * @property { HTMLElement } widget.elContent - The content element
     * @property { Object } widget.modules - The modules
     * @property { Array } widget.data - The current data array
     * @property { boolean } widget.destroyed - Flag for destroyed widget.
     * @property { boolean } widget.initialized - Flag for initialized widget.
     * @return { void }
     */
    onAdd: async function (widget) {
      const w = widget;
      const { map } = widget;
      const { el, objToParams } = mx.helpers;

      w._clean = function () {
        map.off("click", getPosition);
      };

      const dict = [{
        attr: "wdpaid",
        label: "WDPA ID"
      }, {
        attr: "iso3",
        label: "Territory ISO3 code"
      }, {
        attr: "parent_iso3",
        label: "Country ISO3 code"
      }, {
        attr: "name",
        label: "Name of the protected area"
      }, {
        attr: "desig_eng",
        label: "Designation in English"
      }, {
        attr: "desig_type",
        label: "Designation type"
      }, {
        attr: "iucn_cat",
        label: "IUCN category"
      }, {
        attr: "status",
        label: "Status"
      }, {
        attr: "status_yr",
        label: "Year of enactment of status"
      }];

      const UI = el('div', {
        style: {
          display: 'flex',
          flexDirection: 'column',
          padding: '10px'
        }
      },
        dict.map(c => {
          return el('div', {
            style: {
              display: 'flex',
              flexDirection: 'row',
              justifyContent: 'flex-start',
              alignItems: 'center',
              marginBottom: '7px'
            }
          },
            el('span', `${c.label}:`, {
              style: {
                height: '100%',
                fontWeight: 'bold',
                whiteSpace: 'nowrap'
              }
            }),
            el('span', '-', {
              id: `${c.attr}_id`,
              style: {
                height: '100%',
                marginLeft: '10px'
              }
            }));
        }));
      w.elContent.appendChild(UI);

      /**
       * Add zoom to clicked feature bbox
       */
      map.on("click", getPosition);

      async function getPosition(e) {
        const data = await fetchWDPAData(e.lngLat.lng, e.lngLat.lat);
        if (data.features.length > 0){
          const wdpa_data = data.features[0].attributes;
          dict.forEach(d => {
            const el = document.getElementById(`${d.attr}_id`);
            el.innerText = wdpa_data[d.attr] || '-';
          });
        } else {
          dict.forEach(d => {
            const el = document.getElementById(`${d.attr}_id`);
            el.innerText = '-';
        });
        }
      };

      async function fetchWDPAData(lng, lat) {
        const query = getQuery(lng, lat);
        const url = new URL(query);
        const response = await fetch(url);
        const data = await response.json();
        return data;
      }

      function getQuery(lng, lat) {
        const url = 'https://data-gis.unep-wcmc.org/server/rest/services/ProtectedSites/The_World_Database_of_Protected_Areas/FeatureServer/1/query?';
        const out = objToParams({
          geometry: `${lng}, ${lat}`,
          geometryType: 'esriGeometryPoint',
          returnGeometry: false,
          inSR: 4326,
          outFields: 'wdpaid,name,iucn_cat,desig_eng,desig_type,status,status_yr,parent_iso3,iso3',
          f: 'json',
          distance: 5,
          units: 'esriSRUnit_StatuteMile'
        });
        return url + out;
      }
    },
    /**
     *
     * Callback called once when the widget is removed or errored
     * @param {Widget} widget Widget instance
     * @return {void}
     */
    onRemove: async function (widget) {
      const w = widget;
      w._clean();
    },
    /**
     *
     * Callback called each time data is received
     * @param {Widget} widget instance
     * @param {Array<Object>} data Array of object / table
     * @return {void}
     */
    onData: async function (widget, data) { },
  };
}

/** 
 * Add functions to handle dashboard events
 * onAdd = Action to execute when the widget is added to the DOM
 * onRemove = Action to execute when the widget is removed
 * onData = Action to execute when data is updated. Data is available with this.data 
 */
return {
  onAdd: function (widget, data) {
    const h = mx.helpers;
    const el = h.el;
    const map = h.getMap();
    const isAltLegend = mx.settings.mode.static || h.isStoryPlaying();
    const view = widget.view;

    // Define the available scenarios and attributes
    const scenarios = ["opt", "bau", "pes"];
    const scenarioLabels = { "opt": "Optimistic", "bau": "Business as Usual", "pes": "Pessimistic" };
    const timePeriods = ["30", "50", "80"];
    const displayValues = ["2015-2045", "2035-2065", "2065-2095"];

    // Create a title
    const elTitle = el('div', {
      innerText: 'Future scenarios',
      style: { fontSize: '20px', fontWeight: 'bold', textAlign: 'center', paddingTop: '20px' }
    });

    // Create toggle buttons for scenarios
    const elScenarioContainer = el('div', {
      style: { display: 'flex', gap: '10px', padding: '20px 30px', justifyContent: 'center' }
    }, ...scenarios.map(scenario => el('button', {
      innerText: scenarioLabels[scenario],
      className: 'toggle-btn',
      style: scenario === "bau" ? { fontWeight: 'bold', backgroundColor: '#ddd' } : {},
      on: ['click', () => selectScenario(scenario)]
    })));

    // Create toggle buttons for time periods
    const elTimeContainer = el('div', {
      style: { display: 'flex', gap: '10px', padding: '20px 30px', justifyContent: 'center' }
    }, ...timePeriods.map((time, index) => el('button', {
      innerText: displayValues[index],
      className: 'toggle-btn',
      style: index === 0 ? { fontWeight: 'bold', backgroundColor: '#ddd' } : {},
      on: ['click', () => selectTime(index)]
    })));

    widget.elContent.appendChild(elTitle);
    widget.elContent.appendChild(elScenarioContainer);
    widget.elContent.appendChild(elTimeContainer);

    let selectedScenario = "bau";
    let selectedTimeIndex = 0;

    /* Function to update scenario selection */
    function selectScenario(scenario) {
      selectedScenario = scenario;
      updateSelection();
      updateToggleStyles(elScenarioContainer, scenarioLabels[scenario]);
    }

    /* Function to update time period selection */
    function selectTime(index) {
      selectedTimeIndex = index;
      updateSelection();
      updateToggleStyles(elTimeContainer, displayValues[index]);
    }

    /* Function to update the map based on selections */
    function updateSelection() {
      const timePeriod = timePeriods[selectedTimeIndex];
      const selectedAttribute = `${selectedScenario}${timePeriod}_ws_x_l`;
      const viewLayers = h.getLayerNamesByPrefix({ prefix: view.id });

      for (const idLayer of viewLayers) {
        const filters = map.getFilter(idLayer);
        for (const filter of filters) {
          if (h.isArray(filter) && h.isArray(filter[1])) {
            filter[1][1] = selectedAttribute;
          }
        }
        map.setFilter(idLayer, filters);
      }
    }

    /* Function to update button styles */
    function updateToggleStyles(container, activeText) {
      Array.from(container.children).forEach(button => {
        if (button.innerText === activeText) {
          button.style.fontWeight = 'bold';
          button.style.backgroundColor = '#ddd';
        } else {
          button.style.fontWeight = 'normal';
          button.style.backgroundColor = '';
        }
      });
    }
  },

  onRemove: function (widget) {
    console.log('remove');
    if (widget.view._elLegendGroup) {
      widget.view._elLegendGroup.remove();
    }
  },

  onData: function (widget, data) {
    // No specific data handling needed
  }
};

