widgets.script:
function handler() {
  const { el } = mx.helpers;

  const FIELDS = [
    { value: 'disaster_stock_displacement', label: 'Disaster stock displacement' },
    { value: 'conflict_stock_displacement', label: 'Conflict stock displacement' },
    { value: 'disaster_internal_displacements', label: 'Disaster internal displacements' },
    { value: 'conflict_internal_displacements', label: 'Conflict internal displacements' }
  ];

  return {
    async onAdd(widget) {
      const wrap = el('div', { style: { padding: '20px' } });

      const label = el(
        'div',
        { style: { fontSize: '13px', color: '#555', marginBottom: '10px' } },
        'Select value column for the map'
      );

      const select = el('select', {
        style: { width: '100%', padding: '6px', fontSize: '13px' }
      });

      for (const f of FIELDS) {
        select.appendChild(el('option', { value: f.value }, f.label));
      }

      // default selection (keep in sync with main if it has a fallback)
      select.value = 'disaster_stock_displacement';

      // helper to send current selection
      const sendSelection = () => {
        const main = widget.findWidget('main');
        if (!main) return console.warn('[field_selector] main widget not found');
        const opt = select.options[select.selectedIndex];
        main.setData([{
          __ctrl: 'setField',
          field: opt.value,
          label: opt.text
        }]);
      };

      // send immediately so main can init with this
      sendSelection();

      // send on change
      select.addEventListener('change', sendSelection);

      wrap.appendChild(label);
      wrap.appendChild(select);
      widget.setContent(wrap);
    },

    async onData() { },
    async onRemove() { }
  };
}

function handler() {
  const { getViewLegend, DynamicJoin } = mx.helpers;

  const ALLOWED_FIELDS = new Set([
    'disaster_stock_displacement',
    'conflict_stock_displacement',
    'disaster_internal_displacements',
    'conflict_internal_displacements'
  ]);

  // Local state
  const local = {
    dj: null,
    widget: null,
    previousClicked: null,
    observers: [],
    currentField: 'disaster_stock_displacement',
    currentLabel: 'Disaster stock displacement',
    inited: false,
    legendLabelEl: null
  };


  function dispatchCountryValues() {
    const { widget, dj, previousClicked } = local;
    if (!widget || !dj || !previousClicked || !previousClicked.length) return;

    const tableFiltered = (dj.getTableFiltered && dj.getTableFiltered()) || [];

    // we expect one country click; if multi, take the first
    const iso3cd = previousClicked[0]?.iso3cd;
    const country = previousClicked[0]?.country || '';
    if (!iso3cd) return;

    // Try to find the joined data row
    const row = tableFiltered.find(r => r.iso3 === iso3cd) || null;

    // Build metrics, falling back to undefined (Summary will render '—')
    const metrics = [
      {
        key: 'conflict_stock_displacement',
        label: 'Conflict stock displacement',
        value: row?.conflict_stock_displacement
      },
      {
        key: 'disaster_stock_displacement',
        label: 'Disaster stock displacement',
        value: row?.disaster_stock_displacement
      },
      {
        key: 'conflict_internal_displacements',
        label: 'Conflict internal displacements',
        value: row?.conflict_internal_displacements
      },
      {
        key: 'disaster_internal_displacements',
        label: 'Disaster internal displacements',
        value: row?.disaster_internal_displacements
      }
    ];

    // Prefer data-side iso3 if present; otherwise fall back to geometry’s iso3cd
    const iso3 = row?.iso3 || iso3cd;

    // Use year only if we actually have a row for this selection
    const year = row?.year;

    const payload = [{
      __fromClick: true,
      country,
      iso3,
      iso3cd,
      year,
      noData: !row,       
      metrics
    }];

    const w = widget.findWidget('country_values');
    if (w) w.setData(payload);
  }


  // small helper: extract setField control from selector widget (value + label)
  function extractCtrl(payload) {
    const arr = Array.isArray(payload) ? payload : [payload];
    let ctrl = null;
    for (const msg of arr) {
      if (msg && msg.__ctrl === 'setField' && typeof msg.field === 'string') {
        ctrl = {
          field: msg.field,
          label: (typeof msg.label === 'string' && msg.label.trim()) ? msg.label.trim() : msg.field
        };
      }
    }
    return ctrl;
  }

  function updateLegendLabel() {
    if (local.legendLabelEl) local.legendLabelEl.textContent = local.currentLabel;
  }

  return {
    async onAdd(widget) {
      const { view, map } = widget;
      local.widget = widget;
      local.dj = new DynamicJoin(map);

      const queued = extractCtrl(widget.data);
      if (queued) {
        local.currentField = queued.field;
        local.currentLabel = queued.label;
      }

      const elLegend = getViewLegend(view.id, { clone: false });
      local.legendLabelEl = document.createElement('div');
      Object.assign(local.legendLabelEl.style, {
        fontSize: '13px',
        color: '#aaa',
        margin: '6px 0 4px 0',
        fontWeight: '450'
      });
      updateLegendLabel();
      if (elLegend && elLegend.parentNode) {
        elLegend.insertAdjacentElement('beforebegin', local.legendLabelEl);
      }

      await local.dj.init({
        useHighlighter: true,
        useApiMapxData: true,
        useApiMapxTiles: true,
        idSourceGeom: "mx_bf7ke_lx1gc_xb51f_35m0r_y5ucg",
        idSourceData: "mx_ccqg5_kqvri_qfvuq_3ar5h_l3a9s",
        fieldsGeom: ["iso3cd", "maplab"],
        fieldsData: [
          "iso3", "year",
          "conflict_stock_displacement", "disaster_stock_displacement",
          "conflict_internal_displacements", "disaster_internal_displacements"
        ],
        field: local.currentField,
        fieldJoinData: "iso3",
        fieldJoinGeom: "iso3cd",
        joinType: 'left',
        showLegendNA: true,
        elSelectContainer: widget.elContent,
        elLegendContainer: elLegend,
        palette: "YlOrRd",
        stat: "k-means",
        classes: 5,
        aggregateFn: "none",
        colorNa: "#ccc",
        dynamicFilters: [{
          name: "year",
          type: "slider",
          single: true,
          integer: true,
          default: 2024
        }],

        onAggregated() { },
        onTableReady() {
          // If a country is already selected (e.g., user clicked before filter stabilization), update values
          dispatchCountryValues(); 
        },
        onTableFiltered() {
          // When filters (e.g., year) change, refresh the values for the selected country
          dispatchCountryValues(); 
        },
        onMapClick(features) {
          const clicked = features.map(f => ({
            iso3cd: f.properties.iso3cd,
            country: f.properties.maplab || '',
          }));
          clicked.__fromClick = true;
          local.previousClicked = clicked;

          // Send to the country_values widget
          dispatchCountryValues(); 
          console.log(clicked)
        }
      });

      local.inited = true;
    },

    async onData(widget, data) {
      const ctrl = extractCtrl(data);
      if (ctrl) {
        local.currentField = ctrl.field;
        local.currentLabel = ctrl.label;
        updateLegendLabel();
        if (local.inited && local.dj) {
          local.dj.options.field = local.currentField;
          await local.dj.refresh();
        }
      }
    },

    async onRemove() {
      local.observers.forEach(mo => mo.disconnect());
      local.observers = [];
      if (local.dj?.destroy) local.dj.destroy();
    }
  };
}

function handler() {
  const { el } = mx.helpers;

  const local = { container: null, titleEl: null, gridEl: null, hintEl: null };

  // basic number formatter (thousands separators)
  const fmt = n => (typeof n === 'number' && isFinite(n))
    ? new Intl.NumberFormat('en', { maximumFractionDigits: 0 }).format(n)
    : '—';

  // Render one metric cell
  function metricCell({ label, value }) {
    const wrap = el('div', {
      style: {
        padding: '10px',
        border: '1px solid #eee',
        borderRadius: '12px',
        boxShadow: '0 1px 2px rgba(0,0,0,.04)'
      }
    });
    const lab = el('div', {
      style: { fontSize: '12px', color: '#555', marginBottom: '6px' }
    }, label);
    const val = el('div', {
      style: { fontSize: '18px', fontWeight: '600' }
    }, fmt(value));
    wrap.appendChild(lab);
    wrap.appendChild(val);
    return wrap;
  }

  return {
    async onAdd(widget) {
      const wrap = el('div', { style: { padding: '12px' } });

      const title = el('div', {
        style: {
          fontSize: '15px',
          fontWeight: '600',
          textAlign: 'center',
          color: '#666',
          marginBottom: '6px'
        }
      }, 'Country values');

      const subtitle = el('div', {
        style: {
          fontSize: '12px',
          textAlign: 'center',
          color: '#777',
          marginBottom: '10px'
        }
      }, 'Click a country on the map');

      const meta = el('div', {
        style: {
          fontSize: '12px',
          textAlign: 'center',
          color: '#555',
          marginBottom: '12px'
        }
      }, '—');

      const grid = el('div', {
        style: {
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '10px'
        }
      });

      wrap.appendChild(title);
      wrap.appendChild(subtitle);
      wrap.appendChild(meta);
      wrap.appendChild(grid);

      local.container = wrap;
      local.titleEl = title;
      local.hintEl = subtitle;
      local.metaEl = meta;
      local.gridEl = grid;

      widget.setContent(wrap);
    },

    async onData(widget, data) {
      if (!local.container) return;

      const msg = Array.isArray(data) ? data[0] : data;
      const { __fromClick, country, iso3, iso3cd, year } = msg || {};
      let { metrics } = msg || {};

      // reset if no interaction yet
      if (!__fromClick) {
        local.hintEl.style.display = 'block';
        local.metaEl.textContent = '—';
        local.gridEl.innerHTML = '';
        return;
      }

      local.hintEl.style.display = 'none';

      // Prefer iso3; fall back to iso3cd if iso3 is absent
      const code = iso3 || iso3cd || '';

      const countryLine = [
        country || '—',
        code ? `(${code})` : '',
        year ? `• ${year}` : ''
      ].filter(Boolean).join(' ');

      local.metaEl.textContent = countryLine || '—';

      // Ensure we always render the 4 expected metrics, even if msg.metrics is missing
      const ensureKeys = [
        { key: 'conflict_stock_displacement', label: 'Conflict stock displacement' },
        { key: 'disaster_stock_displacement', label: 'Disaster stock displacement' },
        { key: 'conflict_internal_displacements', label: 'Conflict internal displacements' },
        { key: 'disaster_internal_displacements', label: 'Disaster internal displacements' }
      ];

      const asMap = new Map((Array.isArray(metrics) ? metrics : []).map(m => [m.key, m]));
      metrics = ensureKeys.map(({ key, label }) => {
        const m = asMap.get(key);
        return { key, label, value: m?.value };
      });

      local.gridEl.innerHTML = '';
      metrics.forEach(m => local.gridEl.appendChild(metricCell({ label: m.label, value: m.value })));
    }

    ,

    async onRemove() {
      local.container = null;
      local.titleEl = null;
      local.gridEl = null;
      local.hintEl = null;
      local.metaEl = null;
    }
  };
}

