      },

      credits: {
        enabled: false
      },

      series: [{
        name: 'Annual fires density',
        data: defaultSerie,
        lineWidth: 2,
        color: '#0b65e3'

      }, {
        name: 'Trend',
        data: defaultSerie,
        lineWidth: 1.5,
        color: '#FFD700',
        marker: {
          enabled: false
        },
        enableMouseTracking: false
      }]

    });

    /*
    widget.chart.renderer.text('* Data for the current year are partial.<br>See metadata for more information.', 490, 308)
        .css({
            fontStyle: 'italic',
