        var firesTable = 'mx_vector_mmsz7_hwa42_4ddw6_pftck';

        /**
         * data extracted from the map
         */
        var countryCode = data.iso3cd;
        var countryName = data.name_0;
        var provinceCode = data.gadm_prov;
        var provinceName = data.name_1;

        /**
         * query on fires table in MapX db
         */
        var sqlFires = mx.helpers.objToParams({
            sql: `SELECT year, month, SUM(count) AS sum FROM ${firesTable} WHERE gadm_prov = '${provinceCode}' GROUP BY year, month ORDER BY year ASC, month ASC`
        });
        var urlFires = apiSql + sqlFires;

        /**
         * fetching data and updating chart
         */
        fetch(urlFires)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok!');
                }
                return response.json();
            })
            .then(data => {
                if (typeof(data) === 'object' && data.type === 'error') {
                    throw new Error(data.msg);
                }

                /**
                 * updating series
                 */
                years.forEach(function(e, i) {
                    var serie = [];
                    var serieCum = [];
                    var firesYear = data.filter(obj => {
                        return obj.year === e;
                    });
                    if (e != Math.max(...years)) {
                        loopMonths(firesYear, serie, 12);
                    } else {
                        loopMonths(firesYear, serie, monthMax);
                    }
                    serie.reduce(function(prev, curr, i) {
                        return serieCum[i] = prev + curr;
                    }, 0);
                    chart.series[i].setData(serieCum, false);
                });

                /**
                 * redraw chart
                 */
                chart.redraw();

                /**
                 * updating subtitle
                 */
                chart.setTitle(null, {
                    text: 'Country: ' + countryName + ' | Province: ' + provinceName
                });

            })
            .catch(err => {
                mx.helpers.modal({
                    title: "Error when fetching data (widget 2)",
                    content: err.message
                });
            });

        /**
         *  Helpers
         */
        function loopMonths(arrIn, arrOut, max) {
            for (var j = 1; j <= max; j++) {
                var obj;
                obj = arrIn.find(obj => {
                    return obj.month === j;
                });
                if (obj === undefined) {
                    arrOut.push(0);
                } else {
                    arrOut.push(Number(obj.sum));
                }
            }
        }
    }
};

