                "gadm_prov, " +
                "year, " +
                "SUM(count) AS total " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                `gadm_prov = '${provinceCode}' ` +
                "GROUP BY " +
                "gadm_prov, " +
                "year " +
                "), " +
                "wdpa AS ( " +
                "SELECT " +
                "gadm_prov, " +
                "year, " +
                "SUM(count) AS wdpa " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                "wdpa = 1 " +
                "AND NOT modis_lcover IN (1, 2, 3, 4, 5) " +
                `AND gadm_prov = '${provinceCode}' ` +
                "GROUP BY " +
                "gadm_prov, " +
                "year " +
                "), " +
                "forest AS ( " +
                "SELECT " +
                "gadm_prov, " +
                "year, " +
                "SUM(count) AS forest " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                "modis_lcover IN (1, 2, 3, 4, 5) " +
                "AND wdpa = 0 " +
                `AND gadm_prov = '${provinceCode}' ` +
                "GROUP BY " +
                "gadm_prov, " +
                "year " +
                "), " +
                "forest_wdpa AS ( " +
                "SELECT " +
                "gadm_prov, " +
                "year, " +
                "SUM(count) AS forest_wdpa " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                "modis_lcover IN (1, 2, 3, 4, 5) " +
                "AND wdpa = 1 " +
                `AND gadm_prov = '${provinceCode}' ` +
                "GROUP BY " +
                "gadm_prov, " +
                "year " +
                ") " +
                "SELECT " +
                "t.year, " +
                "t.total, " +
                "w.wdpa, " +
                "f.forest, " +
                "l.forest_wdpa " +
                "FROM " +
                "total t " +
                "LEFT JOIN wdpa w ON t.gadm_prov = w.gadm_prov " +
                "AND t.year = w.year " +
                "LEFT JOIN forest f ON t.gadm_prov = f.gadm_prov " +
                "AND t.year = f.year " +
                "LEFT JOIN forest_wdpa l ON t.gadm_prov = l.gadm_prov " +
                "AND t.year = l.year " +
                "ORDER BY year ASC"
        });
        var urlFires = apiSql + sqlFires;

        fetch(urlFires)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok!');
                }
                return response.json();
            })
            .then(data => {
