            lineHeight: '11%',
            color: '#666666'
        })
        .add();
        */

  },
  onRemove: function (widget) {
    mx.highlighter.reset();
  },
  onData: function (widget, data) {
    data = data[0];
    var chart = widget.chart;
    var apiSql = widget.apiSql;
    var years = widget.years;
    var yearMax = Math.max(...years);
    var colors = widget.colors;

    /**
     * fires table in MapX db
     */
    var firesTable = 'mx_vector_mmsz7_hwa42_4ddw6_pftck';

    /**
     * data extracted from the map
     */
    var slope = Number(data.sens_slope_y_tot) || 0;
    var intersect = Number(data.sens_int_y_tot) || 0;
    var sens = data.signif_sens_std_y_tot || 0;
    var area = data.iso_0_area_km_2;
    var countryCode = data.iso3cd;
    var countryName = data.maplab;

    /**
    * setup map highlight
    */
    mx.highlighter.set({
      filters: [{
        id: "MX-CY3C3-R9YDU-EXGPW",
        filter: [
          "==",
          ["get", "iso3cd"],
          data.iso3cd
        ],
      }]
    });

    /**
     * query on mx_fires dataset
     */
    var sql = mx.helpers.objToParams({
      sql: `SELECT year, SUM(count) AS sum FROM ${firesTable} WHERE iso3 = '${countryCode}' AND year <= ${yearMax} GROUP BY year ORDER BY year ASC`
    });
    var url = apiSql + sql;

    /**
     * fetching data and updating chart
     */
    fetch(url)
      .then(response => {
        if (!response.ok) {
          throw new Error('Network response was not ok!');
        }
        return response.json();
      })
      .then(data => {
        var serieSum = [];
        var serieTrend = [];

        years.forEach(function (e) {
          var firesYear = data.find(obj => {
            return obj.year === e;
          });
          if (firesYear === undefined) {
            serieSum.push(0);
          } else {
            serieSum.push(Number(firesYear.sum) / area);
          }
          serieTrend.push(slope * e + intersect);
        });

        /**
         * resetting series
         */
        chart.series[0].setData([]);
        chart.series[1].setData([]);


        /**
         * updating trend color
         */
        var obj = colors.find(obj => obj.value == sens);
        chart.series[1].update({
          color: obj.color
        });

        /**
         * updating series
         */
        chart.series[0].setData(serieSum);
        chart.series[1].setData(serieTrend);

        /**
         * updating subtitle
         */
        chart.setTitle(null, {
          text: 'Country: ' + countryName
        });

      })
      .catch(err => {
        mx.helpers.modal({
          title: "Error when fetching data (widget 1)",
          content: err.message
        });
      });
  }
};

/**
 * Add functions to handle dashboard events
 * onAdd = Action to exectute when the widget is added to the DOM
 * onRemove = Action to execute when the widget is removed
 * onData = Action to execute when data is updated. Data is available
with this.data
 */
return {
    onAdd: function(widget) {
        var elContent = widget.elContent;

        /**
         * setting up the API
         */
        mx.settings.api.routes.sql = '/get/sql/?';
        var apiSql = mx.helpers.getApiUrl('sql');
        widget.apiSql = apiSql;

        /**
         * fires table in MapX db
         */
        var firesTable = 'mx_vector_mmsz7_hwa42_4ddw6_pftck';

        /**
         * setting up yearStart
         */
        var yearStart = 2003;

        /**
         * fetching yearEnd, max month for yearEnd
         * and chart initialization
         */
        var sqlYearEnd = mx.helpers.objToParams({
            sql: `SELECT MAX(year) FROM ${firesTable}`
        });
        var urlYearEnd = apiSql + sqlYearEnd;

        fetch(urlYearEnd)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok!');
                }
                return response.json();
            })
            .then(data => {
                if (typeof(data) === 'object' && data.type === 'error') {
                    throw new Error(data.msg);
                }
                var seriesInit = [];
                var years = [];
                widget.years = years;

                var yearEnd = data[0].max;
                var yearsCount = yearEnd - yearStart + 1;

                for (var i = yearStart; i <= yearEnd; i++) {
                    var serie = {
                        name: i.toString(),
                        data: [],
                        lineWidth: 1,
                        marker: {
                            enabled: false
                        },
                        color: getColor(i / yearsCount),
                    };
                    years.push(i);
                    seriesInit.push(serie);
                }

                initChart(seriesInit);

                widget.chart.series[years.length - 1].update({
                    lineWidth: 3,
                    marker: {
                        enabled: true,
                        fillColor: '#000000'
                    },
                });

                return yearEnd;
            }).then(r => {
                var sqlMonthMax = mx.helpers.objToParams({
                    sql: `SELECT MAX(month) FROM ${firesTable} WHERE year = ${r}`
                });
                var urlMonthMax = apiSql + sqlMonthMax;
                return fetch(urlMonthMax)
                    .then(response => {
                        if (!response.ok) {
                            throw new Error('Network response was not ok!');
                        }
                        return response.json();
                    })
                    .then(d => {
                        if (typeof(d) === 'object' && d.type === 'error') {
                            throw new Error(d.msg);
                        }
                        widget.monthMax = d[0].max;
                    });
            })
            .catch(err => {
                mx.helpers.modal({
                    title: "Error when fetching data",
                    content: err.message
                });
            });

        /**
         * init chart
         */
        function initChart(series) {
            widget.chart = widget.modules.highcharts.chart(elContent, {

                chart: {
                    type: 'line',
                    backgroundColor: '#fff',
                    style: {
                        fontFamily: 'Helvetica,Sans,Arial'
                    },
                    marginBottom: 40,
                    width: 655,
                    height: 325
                },

                plotOptions: {
                    series: {
                        events: {
                            legendItemClick: function(event) {
                                if (!this.visible)
                                    return true;

                                var seriesIndex = this.index;
                                var series = this.chart.series;

                                for (var i = 0; i < series.length; i++) {
                                    if (series[i].index != seriesIndex) {
                                        series[i].visible ? series[i].hide() : series[i].show();
                                    }
                                }

                                return false;
                            }
                        }
                    }
                },

                title: {
                    text: 'Monthly fires',
                    style: {
                        fontWeight: 'bold',
                        fontSize: '1.2em',
                        color: '#000000'
                    },
                    margin: 25
                },

                subtitle: {
                    text: '-',
                    style: {
                        fontWeight: 'normal',
                        fontSize: '1.1em',
                        color: '#808080'
                    }
                },

                xAxis: {
                    categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
                    tickmarkPlacement: 'on',
                    lineColor: '#808080',
                    tickColor: '#808080',
                    tickLength: 5,
                    labels: {
                        style: {
                            fontSize: '0.9em',
                            color: '#000000'
                        },
                    },
                    min: 0,
                    max: 11
                },

                yAxis: [{
                    title: {
                        text: 'Cumulative fires',
                        style: {
                            fontWeight: 'normal',
                            fontSize: '1em',
                            color: '#000000'
                        },
                        margin: 10
                    },
                    labels: {
                        formatter: function() {
                            return this.value.toExponential(2);
                        },
                        style: {
                            fontSize: '0.9em',
                            color: '#000000'
                        }
                    },
                    gridLineWidth: 0.5,
                    gridLineColor: '#808080',
                    min: 0
                }],

                tooltip: {
                    shared: false,
                    formatter: function() {
                        return '<b>' + this.x + ' ' + this.series.name + '</b>: <b>' + this.y.toLocaleString('en-US') + '</b>';
                    }
                },

                legend: {
                    layout: 'vertical',
                    backgroundColor: '#FFFFFF',
                    align: 'right',
                    verticalAlign: 'top',
                    itemMarginBottom: 3,
                    itemStyle: {
                        fontWeight: 'normal',
                        fontSize: '0.9em',
                        color: '#151515'
                    },
                    y: 15
                },

                credits: {
                    enabled: false
                },

                series: series

            });
        }

        /**
         *  Helpers
         */
        function getColor(value) {
            var hue = (value * 300).toString(10);
            return ["hsl(", hue, ", 100%, 40%)"].join("");
        }

    },
    onRemove: function(widget) {},
    onData: function(widget, data) {
        data = data[0];
        var chart = widget.chart;
        var apiSql = widget.apiSql;
        var years = widget.years;
        var monthMax = widget.monthMax;
        
        /**
         * fires table in MapX db
         */
        var firesTable = 'mx_vector_mmsz7_hwa42_4ddw6_pftck';

        /**
         * data extracted from the map
         */
        var countryCode = data.iso3cd;
        var countryName = data.maplab;

        /**
         * query on firesTable dataset
         */
        var sqlFires = mx.helpers.objToParams({
            sql: `SELECT year, month, SUM(count) AS sum FROM ${firesTable} WHERE iso3 = '${countryCode}' GROUP BY year, month ORDER BY year ASC, month ASC`
        });
        var urlFires = apiSql + sqlFires;

        /**
         * fetching data and updating chart
         */
        fetch(urlFires)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok!');
                }
                return response.json();
            })
            .then(data => {
                if (typeof(data) === 'object' && data.type === 'error') {
                    throw new Error(data.msg);
                }

                /**
                 * updating series
                 */
                years.forEach(function(e, i) {
                    var serie = [];
                    var serieCum = [];
                    var firesYear = data.filter(obj => {
                        return obj.year === e;
                    });
                    if (e != Math.max(...years)) {
                        loopMonths(firesYear, serie, 12);
                    } else {
                        loopMonths(firesYear, serie, monthMax);
                    }
                    serie.reduce(function(prev, curr, i) {
                        return serieCum[i] = prev + curr;
                    }, 0);
                    chart.series[i].setData(serieCum, false);
                });

                /**
                 * redraw chart
                 */
                chart.redraw();

                /**
                 * updating subtitle
                 */
                chart.setTitle(null, {
                    text: 'Country: ' + countryName
                });

            })
            .catch(err => {
                mx.helpers.modal({
                    title: "Error when fetching data (widget 2)",
                    content: err.message
                });
            });

        /**
         *  Helpers
         */
        function loopMonths(arrIn, arrOut, max) {
            for (var j = 1; j <= max; j++) {
                var obj;
                obj = arrIn.find(obj => {
                    return obj.month === j;
                });
                if (obj === undefined) {
                    arrOut.push(0);
                } else {
                    arrOut.push(Number(obj.sum));
                }
            }
        }
    }
};

