                return response.json();
            })
            .then(data => {
                if (typeof(data) === 'object' && data.type === 'error') {
                    throw new Error(data.msg);
                }

                data.forEach(function(e) {
                    landCover.push(e.modis_lcover);
                });

                /**
                 * query on mx_fires dataset
                 */
                var sqlFires = mx.helpers.objToParams({
                    sql: `SELECT year, modis_lcover, SUM(count) AS value FROM ${firesTable} WHERE iso3 = '${countryCode}' GROUP BY year, modis_lcover ORDER BY year ASC, modis_lcover asc`
                });
                var urlFires = apiSql + sqlFires;
                /**
                 * fetching data and updating chart
                 */
                return fetch(urlFires)
                    .then(response => {
                        if (!response.ok) {
                            throw new Error('Network response was not ok!');
                        }
                        return response.json();
                    })
                    .then(data => {
                        if (typeof(data) === 'object' && data.type === 'error') {
                            throw new Error(data.msg);
                        }

                        /**
                         * removing all series
                         */
                        var s = chart.series.length;
                        while (s--) {
                            chart.series[s].remove(false);
                        }

                        /**
                         * adding series
                         */
                        landCover.forEach(function(lc) {
                            var dataSerie = [];
                            var firesLCover = data.filter(obj => {
                                return obj.modis_lcover === lc;
                            });

                            years.forEach(function(y) {
                                var firesLCoverYear = firesLCover.find(obj => {
                                    return obj.year === y;
                                });
                                if (firesLCoverYear === undefined) {
                                    dataSerie.push(0);
                                } else {
                                    dataSerie.push(Number(firesLCoverYear.value));
                                }
                            });

                            var modisLC = modis.find(obj => {
                                return obj.value === lc;
                            });

                            chart.addSeries({
                                name: modisLC.name,
                                data: dataSerie
                            }, false);

                        });

                        /**
                         * redraw chart
                         */
                        chart.redraw();

                        /**
                         * updating subtitle
                         */
                        chart.setTitle(null, {
                            text: 'Country: ' + countryName
                        });

                    });
            })
            .catch(err => {
                mx.helpers.modal({
                    title: "Error when fetching data (widget 3)",
                    content: err.message
                });
            });
