                "WHERE " +
                `iso3 = '${countryCode}' ` +
                "GROUP BY " +
                "iso3, " +
                "year " +
                "), " +
                "wdpa AS ( " +
                "SELECT " +
                "iso3, " +
                "year, " +
                "SUM(count) AS wdpa " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                "wdpa = 1 " +
                "AND NOT modis_lcover IN (1, 2, 3, 4, 5) " +
                `AND iso3 = '${countryCode}' ` +
                "GROUP BY " +
                "iso3, " +
                "year " +
                "), " +
                "forest AS ( " +
                "SELECT " +
                "iso3, " +
                "year, " +
                "SUM(count) AS forest " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                "modis_lcover IN (1, 2, 3, 4, 5) " +
                "AND wdpa = 0 " +
                `AND iso3 = '${countryCode}' ` +
                "GROUP BY " +
                "iso3, " +
                "year " +
                "), " +
                "forest_wdpa AS ( " +
                "SELECT " +
                "iso3, " +
                "year, " +
                "SUM(count) AS forest_wdpa " +
                "FROM " +
                `${firesTable} ` +
                "WHERE " +
                "modis_lcover IN (1, 2, 3, 4, 5) " +
                "AND wdpa = 1 " +
                `AND iso3 = '${countryCode}' ` +
                "GROUP BY " +
                "iso3, " +
                "year " +
                ") " +
                "SELECT " +
                "t.year, " +
                "t.total, " +
                "w.wdpa, " +
                "f.forest, " +
                "l.forest_wdpa " +
                "FROM " +
                "total t " +
                "LEFT JOIN wdpa w ON t.iso3 = w.iso3 " +
                "AND t.year = w.year " +
                "LEFT JOIN forest f ON t.iso3 = f.iso3 " +
                "AND t.year = f.year " +
                "LEFT JOIN forest_wdpa l ON t.iso3 = l.iso3 " +
                "AND t.year = l.year " +
                "ORDER BY year ASC"
        });
        var urlFires = apiSql + sqlFires;

        fetch(urlFires)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok!');
                }
                return response.json();
            })
            .then(data => {
                if (typeof(data) === 'object' && data.type === 'error') {
                    throw new Error(data.msg);
                }


                var wdpaForest = [];
                var wdpa = [];
                var forest = [];
                var others = [];

                /**
                 * updating series
                 */
                years.forEach(function(e) {
                    var firesYear = data.find(obj => {
                        return obj.year === e;
                    });

                    /**
                     * test result and if available convert string to number
                     */
                    if (firesYear === undefined) {
                        firesYear = {
                            forest: 0,
                            forest_wdpa: 0,
                            total: 0,
                            wdpa: 0,
                            year: e
                        };
                    } else {
                        firesYear.forest = Number(firesYear.forest);
                        firesYear.wdpa = Number(firesYear.wdpa);
                        firesYear.forest_wdpa = Number(firesYear.forest_wdpa);
                        firesYear.others = Number(firesYear.others);
                    }



                    wdpaForest.push(firesYear.forest_wdpa);
                    wdpa.push(firesYear.wdpa);
                    forest.push(firesYear.forest);
                    others.push(firesYear.total - firesYear.wdpa - firesYear.forest - firesYear.forest_wdpa);
                });

                chart.series[0].setData(wdpa, false, true, false);
                chart.series[1].setData(wdpaForest, false, true, false);
                chart.series[2].setData(forest, false, true, false);
                chart.series[3].setData(others, false, true, false);

                /**
                 * redraw chart
                 */
                chart.redraw();

                /**
                 * updating subtitle
                 */
                chart.setTitle(null, {
                    text: 'Country: ' + countryName
                });

            })
            .catch(err => {
                mx.helpers.modal({
                    title: "Error when fetching data (widget 4)",
                    content: err.message
                });
            });
    }
};

